let currentBook=null,pageIndex=0;
const overlay=document.getElementById("overlay"),leftContent=document.getElementById("leftContent"),rightContent=document.getElementById("rightContent"),openBook=document.getElementById("openBook");
const songs=[["Conjunction Junction","Grammar"],["Lolly, Lolly, Lolly, Get Your Adverbs Here","Grammar"],["Unpack Your Adjectives","Grammar"],["Verb: That’s What’s Happening","Grammar"],["A Noun Is a Person, Place, or Thing","Grammar"],["Interjections!","Grammar"],["Busy Prepositions","Grammar"],["The Tale of Mr. Morton","Grammar"],["Three Is a Magic Number","Math"],["I’m Just a Bill","Civics"],["Interplanet Janet","Science"],["The Great American Melting Pot","Social studies"],["Rufus Xavier Sarsaparilla","Grammar"],["The Shot Heard ’Round the World","History"],["Electricity, Electricity","Science"],["A Victim of Gravity","Science"],["The Preamble","Civics"],["Elbow Room","History"]];
function renderBook(){const b=bookData[currentBook],shell=document.querySelector(".reader-shell");shell.className="reader-shell "+(b.theme||"");const max=Math.max(0,b.pages.length-2);if(pageIndex>max)pageIndex=max;leftContent.innerHTML=b.pages[pageIndex]||"";rightContent.innerHTML=b.pages[pageIndex+1]||"";const referenceArt={stars:[["/images/star-ledger-left.webp","The Star Ledger opening page"],["/images/star-ledger-right.webp","The Star Ledger star contents page"]],brainstorm:[["/images/idea-table-cover-page.webp","The Idea Table cover page"],["/images/idea-table-contents-page.webp","The Idea Table contents page"]]};const oldSpread=openBook.querySelector(".full-opening-spread");if(oldSpread)oldSpread.remove();openBook.classList.remove("illustrated-opening");if(pageIndex===0&&referenceArt[currentBook]){const pages=referenceArt[currentBook];const figure=document.createElement("figure");figure.className="full-opening-spread split-opening-spread";figure.innerHTML=pages.map(([src,alt])=>`<img src="${src}" alt="${alt}">`).join("");openBook.appendChild(figure);openBook.classList.add("illustrated-opening");leftContent.innerHTML="";rightContent.innerHTML="";}document.getElementById("leftNum").textContent=String(pageIndex+1);document.getElementById("rightNum").textContent=String(pageIndex+2);document.getElementById("readerCounter").textContent=b.label;document.getElementById("spreadCounter").textContent=String(Math.floor(pageIndex/2)+1).padStart(2,"0")+" / "+String(Math.ceil(b.pages.length/2)).padStart(2,"0");document.getElementById("prevPage").disabled=pageIndex===0;document.getElementById("nextPage").disabled=pageIndex+2>=b.pages.length;if(currentBook==="music"){const list=document.getElementById("songList");if(list)list.innerHTML=songs.map(([song,category])=>'<a class="song-link" target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/results?search_query='+encodeURIComponent("Schoolhouse Rock "+song+" official")+'"><span>♫</span><span><small>'+category+'</small><br>'+song+'</span><span>↗</span></a>').join("");}}
function openAbook(id){currentBook=id;pageIndex=0;renderBook();overlay.classList.add("show");overlay.setAttribute("aria-hidden","false");document.body.style.overflow="hidden";document.getElementById("closeBook").focus();}
function closeAbook(){overlay.classList.remove("show");overlay.setAttribute("aria-hidden","true");document.body.style.overflow="";}
function turnPage(direction){const next=pageIndex+direction*2;if(next<0||next+1>=bookData[currentBook].pages.length)return;openBook.classList.remove("turning");void openBook.offsetWidth;openBook.classList.add("turning");window.setTimeout(()=>{pageIndex=next;renderBook();},150);}
document.querySelectorAll(".book").forEach(button=>button.addEventListener("click",()=>openAbook(button.dataset.book)));
document.getElementById("closeBook").addEventListener("click",closeAbook);document.getElementById("prevPage").addEventListener("click",()=>turnPage(-1));document.getElementById("nextPage").addEventListener("click",()=>turnPage(1));overlay.addEventListener("click",event=>{if(event.target===overlay)closeAbook();});
const aboutModal=document.getElementById("aboutModal");document.addEventListener("keydown",event=>{if(event.key==="Escape"){closeAbook();aboutModal.classList.remove("show");}if(overlay.classList.contains("show")&&event.key==="ArrowRight")turnPage(1);if(overlay.classList.contains("show")&&event.key==="ArrowLeft")turnPage(-1);});
document.getElementById("aboutBtn").addEventListener("click",()=>{aboutModal.classList.add("show");aboutModal.setAttribute("aria-hidden","false");});document.getElementById("closeAbout").addEventListener("click",()=>{aboutModal.classList.remove("show");aboutModal.setAttribute("aria-hidden","true");});aboutModal.addEventListener("click",event=>{if(event.target===aboutModal)aboutModal.classList.remove("show");});